"""논문형 본문의 1 서론과 2 연구 방법 절. 수치는 저장된 결과 표·JSON과 자료 행 수에서 읽는다."""
import json

import pandas as pd


def _load(path):
    return json.loads(path.read_text(encoding="utf-8"))


def _num(x):
    return f"{int(round(x)):,}"


def _pc(x, d=1):
    return f"{x * 100:.{d}f}%"


def _f3(x):
    return f"{x:.3f}".replace("-", "−")


def _s4(x):
    return f"{x:+.4f}".replace("-", "−")


def build(P):
    T, O = P.tables, P.out
    REP = _load(O / "결과_T1_T2.json")
    MAIN = pd.read_csv(T / "주요결과_T1_T2.csv")
    sr = lambda k: float(MAIN[(MAIN.ruler == "T1") & (MAIN.strategy == k)].SR_test.iloc[0])
    LJ = _load(T / "랩_요약.json")
    FJ = _load(T / "FOC_요약.json")
    BJ = _load(T / "채권2_요약.json")
    Q = float(pd.read_csv(T / "v3_판정.csv").set_index("model").loc["V3", "q_star"])
    REPR = pd.read_csv(T / "대표성_연도별.csv")
    R18, R13 = REPR[REPR.yr <= 2018], REPR[REPR.yr <= 2013]
    APP_N, REJ_N = R18.승인_대출.sum(), R18.거절_신청.sum()
    PSHARE = APP_N / (APP_N + REJ_N)
    CZ = pd.read_csv(T / "중도절단_연도별.csv").set_index("발급연도")
    ALT = pd.read_csv(P.root / "산출물" / "대안모델" / "_work" / "results.csv").set_index("id")
    NFOLD = int(ALT.loc["B0_full", "rows"])
    N_TR_RAW = len(pd.read_csv(P.root / "lending_club_2020_train.csv", usecols=[0]))
    N_TE_RAW = len(pd.read_csv(P.root / "lending_club_2020_test.csv", usecols=[0]))
    N_TR, N_TE = REP["n_train_confirmed"], REP["n_test"]
    N_TUNE = N_TR - NFOLD
    dti_lo, dti_hi = BJ["dti_분위경계"]
    conf = lambda y: CZ.loc[y, "결과확정비율"]
    FOC_LO, FOC_HI = FJ["차이_구간"]
    fico_lo, fico_hi = R13.거절_FICO_중앙.min(), R13.거절_FICO_중앙.max()
    appr_lo, appr_hi = R13.승인_FICO_중앙.min(), R13.승인_FICO_중앙.max()
    h = []

    # ---------------- 1 서론
    h.append(P.h2("1 서론"))
    h.append(P.h3("1.1 연구 배경"))
    h.append(P.p("대출 투자자는 신청이 들어올 때마다 두 길 가운데 하나를 고른다. 대출을 승인해 자금을 차주에게 빌려주거나, 같은 자금을 같은 만기의 국채에 넣는 것이다. 본 연구는 국채를 무위험 자산의 대리 수익으로 쓴다. 승인한 대출은 국채보다 나은 수익을 남길 때에만 자금을 쓸 가치가 있으므로, 승인 결정은 대출 하나의 부도 여부가 아니라 포트폴리오 전체의 성과로 평가되어야 한다."))
    h.append(P.p("그렇다면 부도확률을 정확히 맞히는 모형이 곧 좋은 승인 규칙인가. 그렇지 않다. 신용이 좋은 차주는 부도 위험이 낮은 만큼 약정금리도 낮게 책정되어, 부도가 나지 않더라도 그 금리 차이가 국채를 크게 웃돌지 못할 수 있다. 반대로 부도확률이 다소 높은 대출이 높은 금리 덕분에 더 큰 초과수익을 줄 수도 있다. 부도 예측의 정확도와 Sharpe 비율은 서로 다른 목표이므로, 본 연구는 부도확률 순위를 따르는 전략을 기준으로 두고 Sharpe 비율 자체를 최대로 만드는 규칙을 찾는다."))
    h.append(P.p("자료에는 선택의 문제도 있다. 플랫폼이 승인한 대출만 상환 결과가 관측되며, 거절된 신청자의 상환 결과는 어디에도 남지 않는다. 모형은 승인된 집단 안에서 학습되므로 그 결과를 전체 신청자에게 그대로 옮길 수 없다. 본 연구의 성과는 플랫폼이 이미 승인한 대출 가운데서 다시 고르는 2차 선별의 성과이며, 이 해석의 범위는 4장에서 다시 다룬다."))
    h.append(P.p("세 번째 배경은 대출의 구조이다. 36개월과 60개월 대출은 약정금리에 따라 매달 같은 금액을 나누어 갚는 상각형 구조를 가지므로, 매달 이자와 원금을 지급하는 상각 채권과 같다. 채권과 다른 점은 중도 상환, 부도, 부도 뒤의 회수라는 세 가지뿐이다. 이 대응이 성립하면 채권 분석의 도구인 현재가치, 만기수익률, 스프레드, 충격에 대한 민감도를 대출에도 적용할 수 있다. 이 대응은 2.5절에서 정리한다."))
    h.append(P.h3("1.2 연구 목적과 기여"))
    h.append(P.p("본 연구의 목적은 P2P 대출 자료에서 Sharpe 비율을 높이는 승인 규칙을 도출하고, 그 규칙이 예측 오차, 분류 경계, 채권 가격 분해와 어떻게 이어지는지 보이는 것이다. 이를 위해 다음 네 가지를 기여로 제시한다."))
    h.append(P.steps([
        "<b>승인 규칙의 명시적 유도.</b> 대출 하나를 거절에서 승인으로 바꿀 때 포트폴리오 Sharpe 비율이 어떻게 변하는지 1계조건으로 나누어 적었다. 그 결과 승인 기준은 기대 초과수익에서 위험 비용을 뺀 식이 되며, 위험 비용의 계수 λ = SR/(2σ<sub>p</sub>)는 분산 한 단위가 Sharpe 비율에 주는 비용으로 해석된다.",
        "<b>예측의 두 단계 분해.</b> 대출 수익을 완납과 부도가 섞인 혼합분포로 보고, 부도확률과 조건부 수익을 따로 예측한 뒤 두 값의 1차·2차 모먼트로 승인 점수를 만든다. 잔차를 집단별로 나누어 이 구조가 자료에 나타나는지 점검하였다.",
        "<b>같은 잣대의 평가 설계.</b> 학습 자료 안의 교차검증으로 모형과 승인율을 고르고, 시험 자료에는 고정된 규칙을 한 번만 적용한다. 모든 비교는 발급월을 단위로 한 블록 부트스트랩의 쌍체 차이로 판정한다.",
        "<b>대출의 채권 가격 분해.</b> 대출을 상각 채권으로 옮기는 대응표를 만들고, 현금흐름, 만기수익률, 스프레드 워터폴, 충격 실험으로 만기, 등급, 상환부담(DTI) 조건별 위험 대비 수익을 계량한다.",
    ]))
    h.append(P.p(f"다만 첫 번째 기여의 의미는 성과의 우위가 아니다. 같은 예측에 두 규칙을 적용했을 때 시험 Sharpe의 차이는 {_s4(FJ['차이_foc_v3'])}이고 95% 구간 [{_s4(FOC_LO)}, {_s4(FOC_HI)}]은 0을 포함하므로, 이 자료에서 두 규칙은 통계적으로 구분되지 않는다. 최종 모형의 시험 Sharpe는 {_f3(sr('V3'))}으로, 부도확률 순위({_f3(sr('B0'))})와 전부 승인({_f3(sr('ALL'))})을 크게 웃돈다. 1계조건 규칙의 가치는 더 높은 성과가 아니라, 승인 기준을 명시적으로 유도하고 위험의 가격을 해석 가능한 모수로 표현할 수 있다는 데 있다."))
    h.append(P.h3("1.3 논문의 구성"))
    h.append(P.p("2장은 연구 방법으로, 자료와 표본 분할, 1계조건 승인 규칙, 예측 모형, 분류 모형, 채권 가격 모형, 평가 지표를 차례로 설명한다. 3장은 결과로서 예측 오차의 축소, 분류와 결정 경계, 1계조건 규칙의 성과, 같은 잣대 비교와 강건성, 채권 가격 분해와 취약 구간, 시장 상태와 상대 스프레드를 다룬다. 4장은 결과를 논의하고 분석의 한계와 보완 방안을 정리한 뒤 결론을 맺는다."))

    # ---------------- 2 연구 방법
    h.append(P.h2("2 연구 방법", page=True))
    h.append(P.h3("2.1 자료와 표본 분할"))
    h.append(P.p(f"자료는 LendingClub에서 2007년 6월부터 2020년 9월 사이에 발급된 대출이다. 학습 자료는 원본 {_num(N_TR_RAW)}행이고, 시험 자료는 원자료에서 무작위로 뽑은 40% 표본으로 원본 {_num(N_TE_RAW)}행이다. 두 자료는 같은 기간에 발급되었으나 겹치는 대출이 없다. 분석은 상환 결과가 완납, 상각, 부도로 확정된 대출만 쓰며, 정책 기준을 충족하지 않는 상태의 대출은 제외하였다. 결과 확정 대출은 학습 자료 {_num(N_TR)}건(부도율 {_pc(REP['default_train'], 2)}), 시험 자료 {_num(N_TE)}건(부도율 {_pc(REP['default_test'], 2)})이다."))
    h.append(P.p(f"자료의 역할은 [[t:ip_data]]에 정리하였다. 학습 자료의 결과 확정 대출 가운데 약 10%인 {_num(N_TUNE)}건은 모형 설정을 찾는 튜닝 보류 구간으로 떼어 두었고, 나머지 {_num(NFOLD)}건을 5겹 교차검증의 풀로 쓴다. 각 겹에서 네 겹으로 적합한 모형을 남은 한 겹에서 검증하고, 다섯 겹의 검증 예측을 모아 out-of-fold 값을 만든다. 부스팅 모형의 라운드 수는 학습 겹 안의 무작위 10%로 정한다. 시험 자료는 모형, 승인율, 규칙이 모두 정해진 뒤 한 번만 채점에 쓴다."))
    h.append(P.p(f"소표본 실험은 학습 자료에서 무작위로 뽑은 {_num(LJ['N'])}건으로 수행한다. 이 표본을 학습 {_num(LJ['학습'])}건, 검증 {_num(LJ['검증'])}건, 점검 {_num(LJ['점검'])}건으로 나누고, 표본과 분할을 시드별로 새로 뽑아 {LJ['반복']}회 반복한다. 하이퍼파라미터는 검증 구간에서만 고르고, 점검 구간은 고른 값을 한 번 채점하는 데 쓴다. 이 실험은 전체 자료에 아이디어를 넣기 전에 각 요소의 효과를 작은 표본에서 가늠하려는 것이다."))
    h.append(P.tab("ip_data", "자료의 구성과 역할(건수)", ["자료", "구간", "역할", "건수"], [
        ["학습", "원본 행", "전체 발급 대출", _num(N_TR_RAW)],
        ["학습", "결과 확정 대출", f"완납·부도 결과가 확정된 대출, 부도율 {_pc(REP['default_train'], 2)}", _num(N_TR)],
        ["학습", "튜닝 보류", "점검(hold-out): 모형 설정 선택 전용", _num(N_TUNE)],
        ["학습", "교차검증 풀", "5겹 중 학습 4겹, 검증 1겹(겹마다 교대)", _num(NFOLD)],
        ["학습", "조기 종료 보류", "학습 겹 안의 무작위 10%: 라운드 수 선택", "학습 겹의 10%"],
        ["시험", "원본 행", "원자료에서 무작위로 뽑은 40% 표본", _num(N_TE_RAW)],
        ["시험", "결과 확정 대출", f"고정 규칙의 1회 채점, 부도율 {_pc(REP['default_test'], 2)}", _num(N_TE)],
        ["소표본", "무작위 추출 표본", f"학습 {_num(LJ['학습'])} · 검증 {_num(LJ['검증'])} · 점검 {_num(LJ['점검'])}, {LJ['반복']}회 반복", _num(LJ["N"])],
    ], widths=["14%", "24%", "44%", "18%"]))
    h.append(P.p(f"두 자료는 승인된 대출만 담고 있다. 2007년부터 2018년까지의 신청 가운데 승인된 대출은 {_num(APP_N)}건으로 전체 신청 {_num(APP_N + REJ_N)}건의 {_pc(PSHARE)}에 해당한다. 플랫폼 승인율은 연도별로 약 {_pc(R18.플랫폼_승인율.min(), 0)}에서 {_pc(R18.플랫폼_승인율.max(), 0)} 사이였고 2016년 이후 낮아졌다. 2007년부터 2013년까지 거절 신청자의 FICO 중앙값은 {fico_lo:.0f}~{fico_hi:.0f}점으로, 승인 대출의 {appr_lo:.0f}~{appr_hi:.0f}점보다 뚜렷이 낮았고 매년 절반 이상이 660점 미만이었다. 따라서 본 연구의 성과는 플랫폼이 이미 승인한 집단 안에서 다시 고르는 2차 선별의 성과로 읽어야 하며, 전체 신청자에게 옮기려면 거절 추론이 필요하다."))
    h.append(P.p(f"최근 발급분에는 아직 상환 중인 대출이 많아, 결과가 확정된 대출만 보면 일찍 끝난 대출이 과대표된다. 36개월 대출의 결과 확정 비율은 2016년까지 99.9% 이상이었으나 2017년 {_pc(conf(2017), 0)}, 2018년 {_pc(conf(2018), 0)}, 2019년 {_pc(conf(2019), 0)}로 떨어졌다. 2018년 발급분에서 확정 대출의 부도율은 {_pc(CZ.loc[2018, '확정대출_부도율'])}이지만, 상환 중인 대출을 중도절단으로 넣은 경쟁위험 누적부도율은 {_pc(CZ.loc[2018, '누적부도_36개월'])}이다. 주 지표는 과제 정의에 따라 확정 대출 전체로 계산하고, 만기 코호트 기준 잣대와 생존분석으로 결론이 유지되는지 함께 본다."))

    h.append(P.h3("2.2 승인 규칙: Sharpe 비율의 1계조건"))
    h.append(P.p("승인 규칙의 출발점은 포트폴리오의 Sharpe 비율이다. N개 대출의 포트폴리오에서 대출 i가 승인되면 포트폴리오 수익은 그 대출의 수익 r<sub>i</sub>가 되고, 거절되면 같은 발급월과 만기의 국채 수익 r<sub>f,i</sub>가 된다. 포트폴리오의 평균, 국채 평균, 분산과 Sharpe 비율은 [[e:ip_port]]과 같이 정의한다."))
    h.append(P.eq("R<sub>p</sub> = (1/N) Σ x<sub>i</sub> &nbsp; R<sub>f</sub> = (1/N) Σ r<sub>f,i</sub> &nbsp; σ<sub>p</sub>² = (1/N) Σ (x<sub>i</sub> − R<sub>p</sub>)² &nbsp; <b>SR</b> = (R<sub>p</sub> − R<sub>f</sub>) / σ<sub>p</sub>", "ip_port"))
    h.append(P.p("대출 i의 승인이 Sharpe 비율에 주는 영향은 그 대출을 거절에서 승인으로 바꾸는 미소 변화로 본다. 평균은 (r<sub>i</sub> − r<sub>f,i</sub>)/N만큼 바뀌고, 분산은 1차 근사에서 [(r<sub>i</sub> − R<sub>p</sub>)² − (r<sub>f,i</sub> − R<sub>p</sub>)²]/N만큼 바뀐다. 분산의 변화는 E[x²]의 변화에서 R<sub>p</sub>²의 변화를 뺀 것이다. 두 변화를 Sharpe 비율의 미분에 대입하면 [[e:ip_dsr]]을 얻는다."))
    h.append(P.eq("dR<sub>p</sub> = (r<sub>i</sub> − r<sub>f,i</sub>) / N &nbsp;&nbsp; dσ<sub>p</sub>² = [(r<sub>i</sub> − R<sub>p</sub>)² − (r<sub>f,i</sub> − R<sub>p</sub>)²] / N<br>dSR = (1/σ<sub>p</sub>) [ dR<sub>p</sub> − (SR / (2σ<sub>p</sub>)) dσ<sub>p</sub>² ]", "ip_dsr"))
    h.append(P.p("괄호 안 둘째 항의 계수가 위험회피 계수이다. [[e:ip_lambda]]로 정의하며, 분산이 한 단위 늘 때 Sharpe 비율에 치르는 비용을 뜻한다. 현재 포트폴리오의 Sharpe 비율이 높을수록, 표준편차가 작을수록 이 계수는 커진다."))
    h.append(P.eq("λ = SR / (2σ<sub>p</sub>)", "ip_lambda"))
    h.append(P.p("승인 조건은 dSR &gt; 0이다. [[e:ip_dsr]]의 양변에 N을 곱하면 r<sub>i</sub> − r<sub>f,i</sub> − λ[(r<sub>i</sub> − R<sub>p</sub>)² − (r<sub>f,i</sub> − R<sub>p</sub>)²] &gt; 0을 얻는다. r<sub>i</sub>는 미래의 값이므로 기댓값으로 바꾼다. E[(r<sub>i</sub> − R<sub>p</sub>)²] = Var(r<sub>i</sub>) + (E r<sub>i</sub> − R<sub>p</sub>)²를 대입하면 승인 조건은 [[e:ip_foc]]가 된다. 대출 사이의 공분산은 0으로 두었다."))
    h.append(P.eq("E r<sub>i</sub> − r<sub>f,i</sub> − λ · { Var(r<sub>i</sub>) + (E r<sub>i</sub> − R<sub>p</sub>)² − (r<sub>f,i</sub> − R<sub>p</sub>)² } &gt; 0 &nbsp;&nbsp; ⇒ 승인", "ip_foc"))
    h.append(P.p("식의 첫 항은 대출이 주는 기대 초과수익이고, 중괄호 안은 그 대출이 포트폴리오 분산에 더하는 몫이다. 비율 순위 규칙은 기대 초과수익을 표준편차로 나눈 값으로 줄을 세운다. 두 규칙은 위험을 다르게 벌준다. 비율 규칙은 위험을 표준편차에 비례하게 벌주는 반면, 1계조건 규칙은 분산 기여를 이차식으로 계산하고 포트폴리오 평균과의 거리까지 반영한다."))
    h.append(P.p("기댓값과 분산은 부도확률과 조건부 수익으로 계산한다. p<sub>i</sub>를 부도확률, a<sub>i</sub>와 d<sub>i</sub>를 완납과 부도 시의 수익, σ<sub>a</sub>²와 σ<sub>d</sub>²를 두 집단의 잔차 분산으로 두면 [[e:ip_mix]]와 같다."))
    h.append(P.eq("E r<sub>i</sub> = (1 − p<sub>i</sub>) a<sub>i</sub> + p<sub>i</sub> d<sub>i</sub><br>Var(r<sub>i</sub>) = (1 − p<sub>i</sub>) σ<sub>a</sub>² + p<sub>i</sub> σ<sub>d</sub>² + p<sub>i</sub>(1 − p<sub>i</sub>)(a<sub>i</sub> − d<sub>i</sub>)²", "ip_mix"))
    h.append(P.p("실제 승인 집합은 R<sub>p</sub>와 함께 정해지므로, 승인 집합에서 평균을 다시 계산하는 고정점 반복으로 구한다. λ는 학습 자료 교차검증의 out-of-fold Sharpe를 최대로 하는 값을 0.05에서 500 사이 160개 격자에서 고른다. 이론상 최적에서는 [[e:ip_lambda]]가 성립하므로, 고른 λ가 이 이론값과 얼마나 다른지도 함께 본다. 소표본에서는 같은 규칙을 120개 격자에서 검증 구간으로 고른다."))

    h.append(P.h3("2.3 예측 모형"))
    h.append(P.p("예측의 대상은 대출의 초과수익 z<sub>i</sub> = r<sub>i</sub> − r<sub>f,i</sub>이다. [[e:ip_foc]]의 기대 초과수익 E r<sub>i</sub> − r<sub>f,i</sub>가 바로 이 예측값이다. 소표본 실험에서는 평균만 쓰는 기준선에서 출발해 변수 군을 하나씩 더하고, 정규화 회귀, 2단계 구조, 비선형 모형을 차례로 넣으면서 예측 오차의 변화를 본다. 변수는 가격·약정 6개, 신용이력 46개, 재무 13개, 시장·시기 11개로 모두 76개이며 결측 표지를 포함한다. 사다리의 단계는 다음과 같다."))
    h.append(P.steps([
        "평균만 쓰는 기준선",
        "가격·약정 변수의 최소제곱(OLS)",
        "신용이력 변수 추가",
        "재무 변수 추가",
        "시장·시기 변수 추가(전체 변수 OLS)",
        "Ridge(L2 규제)",
        "Lasso(L1 규제)",
        "2단계: 부도확률 × 조건부 이득",
        "비선형: 히스토그램 부스팅 1단계",
        "히스토그램 부스팅 2단계와 비율 순위(v3-lite)",
    ]))
    h.append(P.p("정규화 회귀는 계수 크기에 벌점을 주어 변수가 많을 때의 과적합을 줄인다. Ridge는 L2 벌점으로 계수를 0 쪽으로 고르게 줄이고, Lasso는 L1 벌점으로 일부 계수를 정확히 0으로 만든다. 벌점의 세기 α는 검증 구간의 RMSE가 가장 작은 값으로 정한다. [[e:ip_reg]]는 세 목적함수를 나타낸다."))
    h.append(P.eq("OLS: min Σ (z<sub>i</sub> − x<sub>i</sub>′β)² &nbsp;&nbsp; Ridge: 위 식 + α‖β‖<sub>2</sub>² &nbsp;&nbsp; Lasso: 위 식 + α‖β‖<sub>1</sub>", "ip_reg"))
    h.append(P.p("학습 자료의 오차는 모형이 복잡해질수록 항상 줄어든다. 그래서 설명력이 높아졌다는 판단은 검증 구간과 점검 구간의 오차가 함께 줄고, 학습 오차와 검증 오차의 차이인 일반화 간격이 커지지 않을 때에만 내린다. 오차의 정의와 세부 지표는 2.6절에서 다룬다."))
    h.append(P.p("최종 모형은 예측을 다섯 단계로 나눈다. 대출 신청 시점에 알 수 있는 변수 71개를 입력으로 쓰며, 상환 이후에만 알 수 있는 사후 정보 31개는 제외하였다. 부도확률만으로 승인하면 안전하지만 금리가 낮은 대출만 남아 국채 대비 초과수익이 작아지기 때문에, 부도확률과 조건부 수익을 따로 예측한다."))
    h.append(P.p("부도확률 p̂는 XGBoost 3개 시드의 평균, LightGBM, CatBoost의 단순 평균으로 추정한다. 완납 대출의 조건부 수익 â와 부도 대출의 조건부 수익 d̂는 각각 XGBoost 회귀로 추정하며, 목표는 과제 잣대 수익에서 국채 수익을 뺀 값이다. 평균 μ̂ = (1 − p̂)â + p̂d̂와 표준편차 σ̂² = p̂(1 − p̂)(â − d̂)² + (1 − p̂)s<sub>a</sub>² + p̂s<sub>d</sub>²로 승인 점수 μ̂/σ̂를 만든다. 이 점수의 상위 q 대출을 승인하고 나머지 자금은 국채에 둔다. s<sub>a</sub>²와 s<sub>d</sub>²는 두 집단의 잔차 분산 추정치이다."))
    h.append(P.p(f"각 구성 요소의 채택은 학습 자료의 교차검증 결과만으로 하였다. 승인율 q는 학습 교차검증 곡선의 최대점을 0.5% 간격 격자에서 고른 값이며, 본 분석에서는 {_pc(Q, 0)}이다. 이 값은 시험 결과를 본 뒤 바꾸지 않았다. 1계조건 규칙은 이 최종 모형의 예측을 그대로 쓰고 승인 규칙만 바꾸어 비율 순위 규칙과 비교한다. 두 규칙이 예측을 공유하므로, 차이는 승인 규칙 자체에서 나온다."))

    h.append(P.h3("2.4 분류 모형: ROC · 임계값 거리 · 소프트마진"))
    h.append(P.p(f"승인 결정은 결국 승인과 거절의 이진 결정이므로 분류 문제로도 볼 수 있다. 부도 점수 s<sub>i</sub>가 클수록 위험이 크다고 하고, 임계값 τ 이상이면 거절한다. 임계값은 승인율 {_pc(Q, 0)}에 해당하는 점수 분위로 둔다. 임계값에 따라 참 양성률(TPR)과 거짓 양성률(FPR)을 그린 곡선이 ROC이며, 그 아래 면적(AUC)은 무작위로 뽑은 부도 대출의 점수가 완납 대출보다 높을 확률이다. 정의는 [[e:ip_class]]와 같다."))
    h.append(P.eq("TPR(τ) = P(s ≥ τ | 부도) &nbsp; FPR(τ) = P(s ≥ τ | 완납) &nbsp; AUC = P(s<sub>부도</sub> &gt; s<sub>완납</sub>)<br>임계값 거리 d<sub>i</sub> = (a<sub>i</sub> − τ) / sd(a) &nbsp; (a<sub>i</sub>는 승인 점수, 클수록 승인) &nbsp;&nbsp; 결정이 맞음 ⇔ (승인하고 z<sub>i</sub> &gt; 0) 또는 (거절하고 z<sub>i</sub> ≤ 0)", "ip_class"))
    h.append(P.p("임계값 거리 d<sub>i</sub>는 점수가 경계에서 떨어진 정도를 점수의 표준편차 단위로 잰 값이다. 경계에 가까운 대출은 작은 예측 오차에도 결정이 뒤집히므로, |d|의 구간별로 결정이 맞은 비율과 평균 |z|를 함께 본다. 이 구간별 정보로 승인 경계 주변을 사람이 다시 심사하는 림보 구간을 정할 수 있는지 판단한다."))
    h.append(P.p("서포트 벡터 머신의 소프트마진 형태도 비교한다. 경계를 넘는 위반은 slack 변수 ξ로 허용하고, 벌점 C로 위반의 정도를 조절한다. 본 연구는 여기에 |z<sub>i</sub>|로 가중한 벌점을 더한다. 큰 이득이나 큰 손실을 가진 대출을 잘못 분류했을 때 더 큰 벌점을 주어 손익의 크기를 반영하기 위함이다. 정의는 [[e:ip_svm]]과 같다."))
    h.append(P.eq("min<sub>w,b</sub> ½‖w‖² + C Σ ξ<sub>i</sub> &nbsp; s.t. t<sub>i</sub>(w′x<sub>i</sub> + b) ≥ 1 − ξ<sub>i</sub>, ξ<sub>i</sub> ≥ 0 &nbsp; (손실은 hinge: max(0, 1 − t<sub>i</sub>f(x<sub>i</sub>)))<br>|z| 가중 벌점: C Σ |z<sub>i</sub>| ξ<sub>i</sub>", "ip_svm"))
    h.append(P.p("C는 모형마다 다른 기준으로 고른다. L2 로지스틱은 검증 구간의 로그손실, L1 로지스틱은 검증 구간의 부도 AUC, SVM과 목표 정렬 로지스틱은 검증 구간의 승인 방향 AUC를 기준으로 한다. 모형 간 차이에는 학습 목표(부도를 맞히는지, 수익의 부호를 맞히는지)와 손실 형태(소프트마진 여부)가 함께 섞인다. 두 효과를 나누기 위해 부도 대신 초과수익의 부호(z &gt; 0)를 목표로 한 로지스틱 회귀를 같은 조건에서 학습해 함께 비교한다."))

    h.append(P.h3("2.5 대출의 채권 가격 모형"))
    h.append(P.p("36개월과 60개월 대출은 약정금리를 매달 나누어 상환하는 상각 채권과 같다. 채권과 다른 점은 세 가지뿐이다. 중도 상환은 채권의 콜옵션에 해당하고, 부도는 신용사건이며, 부도 뒤의 회수금은 회수율(recovery)에 해당한다. [[t:ip_bond]]는 두 구조의 대응을 정리한 것이다. 대출의 월 지급액은 [[e:ip_amort]]로 정해진다."))
    h.append(P.eq("월 지급액 = 대출액 · r / (1 − (1 + r)<sup>−n</sup>) &nbsp;&nbsp; r = 약정금리 / 12 &nbsp;&nbsp; n = 36 또는 60", "ip_amort"))
    h.append(P.p(f"분석 단위는 만기(2), 등급(7), DTI 삼분위(3)로 나눈 {BJ['전체칸']}칸이다. DTI 삼분위의 경계는 {dti_lo}과 {dti_hi}이다. 분석에는 학습 자료에서 결과가 확정되고 만기까지 관측된 대출 {_num(BJ['코호트'])}건을 쓰며, 시험 자료는 이 절에서 쓰지 않는다. 각 칸에서 나이별 조기상환율(SMM), 부도율(MDR), 손실률(LGD)을 추정해 기대 현금흐름을 만들고, 그것으로 만기수익률을 구해 실현 수익률과 맞춘다."))
    h.append(P.p("칸의 현금흐름은 [[e:ip_price]]처럼 이자, 정기 원금, 조기 상환, 부도 뒤 회수금으로 구성된다. 회수금은 부도 잔액의 (1 − LGD)가 6개월 늦게 들어온다고 가정하였다. 만기수익률 y*는 가격을 1로 만드는 할인율이며([[e:ip_ytm]]), 공정 쿠폰 c<sub>rn</sub>은 무위험 금리 r<sub>f</sub>로 할인한 가격을 1로 만드는 쿠폰이다([[e:ip_fair]]). 약정금리와 공정 쿠폰의 차이가 위험 프리미엄이며, 이는 만기수익률에서 국채 금리를 뺀 값과 같은 방향으로 움직인다."))
    h.append(P.eq("P(y) = Σ<sub>t=1</sub><sup>n+ℓ</sup> CF<sub>t</sub> / (1 + y/12)<sup>t</sup><br>CF<sub>t</sub> = 이자<sub>t</sub> + 정기 원금<sub>t</sub> + 조기 상환<sub>t</sub> + (1 − LGD) · 부도 잔액<sub>t−ℓ</sub> &nbsp;&nbsp; ℓ = 6 (회수 지연)", "ip_price"))
    h.append(P.eq("P(y*) = 1 &nbsp;&nbsp; 실현 스프레드 = y* − r<sub>f</sub>", "ip_ytm"))
    h.append(P.eq("Σ<sub>t</sub> CF<sub>t</sub>(c<sub>rn</sub>) / (1 + r<sub>f</sub>/12)<sup>t</sup> = 1 &nbsp;&nbsp; 위험 프리미엄 = 약정금리 − c<sub>rn</sub> ≈ y* − r<sub>f</sub>", "ip_fair"))
    h.append(P.p("약정 스프레드가 실현 스프레드로 줄어드는 과정은 [[e:ip_waterfall]]처럼 단계별로 나눈다. 먼저 부도 손실을 반영하고, 회수금의 기여를 더한 뒤, 마지막으로 수수료를 뺀다. 실현 스프레드를 약정 스프레드로 나눈 값을 보존율로 정의한다."))
    h.append(P.eq("s<sub>약정</sub> = 약정금리 − r<sub>f</sub><br>s<sub>실현</sub> = s<sub>약정</sub> + 손실효과 + 회수효과 + 수수료효과<br>손실효과 = IRR(이자·원금·연체료만) − 약정금리 &nbsp;&nbsp; 회수효과 = 회수금의 기여 &nbsp;&nbsp; 수수료효과 = −(수수료 1% + 회수수수료)의 기여<br>보존율 = s<sub>실현</sub> / s<sub>약정</sub>", "ip_waterfall"))
    h.append(P.p("충격 실험은 부도율, 손실률, 회수 지연, 조기 상환 속도(0.5배, 1.5배), 신용 스트레스의 여섯 가지를 적용해 만기수익률의 변화를 계산한다. 충격에 대한 민감도는 [[e:ip_shock]]의 ΔY로 정의하고, 충격 아래에서도 기준과 같은 가격을 유지하는 쿠폰 가산 Δc를 방어 쿠폰으로 계산한다. 칸의 점수는 [[e:ip_foc]]의 승인 항만 남긴 E[z] − λ*·Var(r)로 계산하며, λ*는 2.2절에서 학습 자료로 고른 값이다."))
    h.append(P.eq("ΔY = y(충격) − y(기준) &nbsp;&nbsp; y(c + Δc, 충격) = y(c, 기준)을 만족하는 Δc = 방어 쿠폰 가산", "ip_shock"))
    h.append(P.tab("ip_bond", "대출과 채권의 대응", ["채권 항목", "대출에서의 대응", "계산에 쓴 값"], [
        ["액면·쿠폰", "대출액 · 약정금리(월복리 명목)", "칸별 금액가중 약정금리"],
        ["만기·상각", "36·60개월 원리금 균등 상환", "월 지급액([[e:ip_amort]]), 원금잔액 감소"],
        ["조기상환 옵션", "중도 완납", "나이별 SMM<sub>t</sub> = 조기상환 잔액 / 위험집합 잔액"],
        ["신용사건", "첫 미납에 따른 부도", "나이별 MDR<sub>t</sub>, 상각 시점 = 마지막 납입 + 6개월"],
        ["회수율(recovery)", "부도 대출의 회수금", "LGD = 1 − Σ(회수 − 회수수수료) / Σ잔액"],
        ["무위험 수익률", "안전자산 = 국채", "발급월 만기 맞춤 국채(36개월 = 3년물, 60개월 = 5년물)"],
        ["스프레드", "안전자산 대비 초과수익", "약정 스프레드, 실현 스프레드, 위험 프리미엄"],
        ["듀레이션·볼록성", "금리·신용 충격에 대한 가격 민감도", "충격별 ΔY(bp), 가격 변화율(%)"],
    ], widths=["18%", "34%", "48%"], foot="SMM: 나이별 조기상환율, MDR: 나이별 부도율, LGD: 손실률, IRR: 내부수익률."))

    h.append(P.h3("2.6 평가 지표와 통계적 비교"))
    h.append(P.p("주 지표는 과제가 정한 포트폴리오 Sharpe 비율이다. 대출 i의 연 수익률은 총 상환액을 투자원금으로 나눈 값의 12/T 제곱에서 1을 뺀 것이며, T는 계약 만기(36 또는 60개월)이다. 포트폴리오 수익은 승인한 대출이면 r<sub>i</sub>, 거절한 신청이면 같은 발급월과 만기의 국채 수익이며, 대출을 같은 가중으로 평균한다([[e:ip_sharpe]]). 전부 거절하면 Sharpe는 0이 되고, 0보다 큰 값은 국채보다 나은 선별로 본다."))
    h.append(P.eq("SR = (x̄ − r̄<sub>f</sub>) / s<sub>x</sub> &nbsp;&nbsp; x<sub>i</sub> = 승인이면 r<sub>i</sub>, 거절이면 r<sub>f,i</sub>", "ip_sharpe"))
    h.append(P.p("계약만기 기준 연율화는 분할상환과 조기상환을 반영하지 못하므로, 3장에서는 듀레이션 기준의 수익률로도 같은 결론이 나오는지 함께 본다. 보조 잣대는 여덟 가지이다. 기회풀 Sharpe는 승인 여부를 곱한 초과수익의 평균을 전체 기회로 나눈 값을 만기 코호트에 적용한다(36개월 대출은 2017년 3월까지, 60개월 대출은 2015년 3월까지 발급분). 대출 단위 Sharpe는 대출별 실현 총수익률에서 국채 금리에 잔액과 연수를 곱한 값을 뺀 평균을 표준편차로 나눈다. 대출 IRR Sharpe는 월 현금흐름의 내부수익률에서 국채를 뺀 값으로, 검증 구간에서 기준을 고른 뒤 무작위 20% 표본에 100회 적용한다. 금액 위험은 승인했지만 부도가 난 금액과 거절했지만 완납되었을 대출의 금액을 합한 것이다."))
    h.append(P.p("발급월 현금흐름 Sharpe는 발급월 묶음별 초과수익의 평균을 표준편차로 나눈다. 보유기간수익률 Sharpe는 중간 현금흐름을 국채로 재투자해 계약만기까지 계산한 보유기간수익률로 구한다. 마지막으로 시간 외 검증은 과거 자료로만 학습한 규칙을 이후 발급분에 적용하며, 2016~17년 발급분과 2017~20년 발급분의 두 구간을 쓴다."))
    h.append(P.p("두 규칙의 비교는 같은 예측에서 같은 대출에 적용한 쌍체 차이로 한다. 대출은 같은 발급월 안에서 함께 움직이므로, 신뢰구간은 발급월을 단위로 복원추출하는 블록 부트스트랩으로 만든 95% 구간이다. 단일 값의 구간은 대출 단위 부트스트랩으로 구한다. 소표본 실험은 20회 반복의 중앙값과, 쌍체 비교에서 앞선 반복의 비율을 함께 보고한다."))
    h.append(P.p("예측 오차는 e<sub>i</sub> = z<sub>i</sub> − ẑ<sub>i</sub>로 정의하고, 학습 구간과 점검 구간의 RMSE를 쓴다. 점검 구간의 설명력은 R² = 1 − Σe² / Σ(z − z̄<sub>학습</sub>)²으로 잰다. 예측이 편향되지 않았는지는 Mincer–Zarnowitz 회귀([[e:ip_mz]])의 α = 0, β = 1을 발급월 군집 표준오차로 검정한다. 분류 성능은 AUC로 보며, 부도 점수의 AUC와 승인 점수가 초과수익의 부호를 맞히는 정도의 AUC를 나누어 본다."))
    h.append(P.eq("z<sub>i</sub> = α + β ẑ<sub>i</sub> + u<sub>i</sub> &nbsp;&nbsp; 불편 ⇔ α = 0, β = 1", "ip_mz"))
    h.append(P.p("본 연구의 가설은 여덟 개이며, 비교 대상과 판정 기준은 [[t:ip_hyp]]에 정리하였다. 각 가설의 판정은 표에 적은 기준을 그대로 적용한다."))
    h.append(P.tab("ip_hyp", "가설과 판정 기준", ["번호", "가설", "비교 대상과 통계량", "판정 기준"], [
        ["H1", "기대 초과수익 기반 순위(최종 모형)가 부도확률 순위보다 시험 Sharpe가 높다", "시험 Sharpe의 쌍체 차이, 발급월 블록 부트스트랩 95% 구간", "구간 하한이 0보다 크면 지지"],
        ["H2", "완납 대출과 부도 대출의 잔차 크기가 다르다", "집단별 잔차 표준편차의 비(부도 대 완납)", "표준편차의 비가 2 이상이면 지지"],
        ["H3", "Ridge와 Lasso가 OLS보다 점검 오차를 줄인다", "같은 표본 쌍에서 점검 RMSE의 차이(20회)", "중앙값 차이가 −0.0005 이하이고 20회 중 15회 이상 더 낮으면 설명력이 높아진 것으로 본다"],
        ["H4", "비선형 모형이 선형 모형보다 설명력이 높다", "소표본: 점검 RMSE 쌍차(20회) / 전체 표본: 부도 AUC 차이", "소표본은 H3과 같은 기준, 전체 표본은 AUC 차이가 0.005 이상이면 지지"],
        ["H5", "1계조건 규칙이 비율 순위 규칙보다 시험 Sharpe가 높다", "같은 예측에서 시험 Sharpe의 쌍체 차이, 발급월 블록 부트스트랩 95% 구간", "구간 하한이 0보다 크면 지지, 구간이 0을 포함하면 두 규칙의 차이가 없다고 본다"],
        ["H6", "임계값에 가까운 대출일수록 결정이 불안정하다", "|d| 구간별 결정이 맞은 비율, |d| &lt; 0.5 구간과 |d| ≥ 1 구간의 차이", "같은 쪽(승인 또는 거절) 안에서 먼 구간의 맞은 비율이 가까운 구간보다 10%p 이상 높으면 지지"],
        ["H7", "소프트마진과 |z| 가중이 순위 품질을 높인다", "목표 정렬 로지스틱 대비 SR26과 AUC의 쌍차(20회)", "SR26 중앙값 차이가 +0.005 이상이고 20회 중 15회 이상 우세하면 지지"],
        ["H8", "신용 환경에는 천천히 움직이는 상태가 있다", "월별 평균 초과수익의 AIC와 한 걸음 앞 예측 RMSE", "AIC가 가장 작고 예측 RMSE가 평균 예측보다 작으면 지지"],
    ], widths=["7%", "31%", "32%", "30%"]))

    return "".join(h)
